import { useEffect, useRef, useCallback } from 'react';

// Timeout par rôle (en millisecondes)
const TIMEOUTS = {
  admin:     2 * 60 * 1000,  // 10 minutes
  chef:      15 * 60 * 1000,  // 15 minutes
  operateur: 20 * 60 * 1000,  // 20 minutes
};

const WARNING_BEFORE = 60 * 1000; // Avertissement 1 minute avant expiration

export function useSessionTimeout({ role, onExpire, onWarning }) {
  const timerRef   = useRef(null);
  const warningRef = useRef(null);
  const timeout    = TIMEOUTS[role] || TIMEOUTS.operateur;

  const resetTimer = useCallback(() => {
    if (timerRef.current)   clearTimeout(timerRef.current);
    if (warningRef.current) clearTimeout(warningRef.current);

    // Avertissement 1 minute avant expiration
    warningRef.current = setTimeout(() => {
      onWarning && onWarning(60);
    }, timeout - WARNING_BEFORE);

    // Expiration de session
    timerRef.current = setTimeout(() => {
      onExpire && onExpire();
    }, timeout);

    // Sauvegarder la dernière activité
    localStorage.setItem('lastActivity', Date.now().toString());
  }, [timeout, onExpire, onWarning]);

  useEffect(() => {
    const lastActivity = parseInt(localStorage.getItem('lastActivity') || '0');
    // Ne vérifier que si lastActivity existe ET est récent (moins de 24h)
    if (lastActivity && 
        Date.now() - lastActivity > timeout && 
        Date.now() - lastActivity < 24 * 60 * 60 * 1000) {
      onExpire && onExpire();
      return;
    }

    const events = ['mousedown', 'mousemove', 'keydown', 'scroll', 'touchstart', 'click'];
    events.forEach(e => window.addEventListener(e, resetTimer));
    resetTimer();

    return () => {
      events.forEach(e => window.removeEventListener(e, resetTimer));
      if (timerRef.current)   clearTimeout(timerRef.current);
      if (warningRef.current) clearTimeout(warningRef.current);
    };
}, [resetTimer, timeout, onExpire]);}
